    essays:[{title:"Eating or sleep disorder",category:"Eating and Sleep Disorders",prompt:"Outline the assessment and initial management of a patient with a suspected eating disorder or persistent insomnia.",max:20,modelAnswer:"Clarify symptoms, duration, function, eating/sleep pattern, weight change, compensatory behaviours, mood, trauma, substance and medical history. Assess medical stability, complications, suicide risk and comorbidity. Explain the formulation and offer appropriate multidisciplinary care; eating disorders may need nutritional, psychological and medical treatment. For insomnia, address contributing conditions, sleep routine and CBT-I where available; avoid unsafe medication reliance and arrange follow-up.",rubric:[{label:"Symptoms and history",points:5,feedback:"Characterise eating/sleep pattern, duration, impairment and relevant history.",groups:[["symptoms","duration"],["eating","sleep"],["impairment","history"]]}, {label:"Risk and physical assessment",points:5,feedback:"Assess medical stability, complications, mood and suicide risk.",groups:[["medical","stability"],["complications","weight"],["suicide","mood"]]}, {label:"Evidence-based management",points:5,feedback:"Use appropriate nutritional/psychological care or CBT-I and address contributors.",groups:[["nutrition","multidisciplinary"],["psychological","therapy"],["CBT-I","sleep"]]}, {label:"Follow-up and safety",points:5,feedback:"Plan monitoring, support, medication caution and review.",groups:[["monitoring","review"],["support","follow up"],["medication","safety"]]}]}]
