    essays:[{title:"Sexual health assessment",category:"Human Sexuality and Gender-Related Presentations",prompt:"Describe a respectful biopsychosocial assessment of a patient presenting with a sexual concern.",max:20,modelAnswer:"Establish privacy, consent and a non-judgemental approach. Clarify the concern, onset, context, distress and goals. Assess medical illness, medications, mental health, substance use, relationship factors and relevant sexual history. Consider consent, coercion, trauma and safeguarding. Explain options collaboratively, arrange targeted investigation or referral, and review response while maintaining confidentiality.",rubric:[{label:"Communication and consent",points:5,feedback:"Ensure privacy, permission, respectful language and confidentiality boundaries.",groups:[["privacy","confidentiality"],["consent","respectful"],["non judgemental","communication"]]}, {label:"Biopsychosocial history",points:5,feedback:"Explore symptoms, medical/medication, psychological and relationship factors.",groups:[["symptoms","onset"],["medical","medication"],["psychological","relationship"]]}, {label:"Safety and safeguarding",points:5,feedback:"Assess consent, coercion, harm and safeguarding where relevant.",groups:[["consent","coercion"],["harm","risk"],["safeguarding","trauma"]]}, {label:"Plan and follow-up",points:5,feedback:"Agree options, investigations/referral and follow-up.",groups:[["options","plan"],["investigation","referral"],["follow up","review"]]}]}]
