    essays:[{title:"Treatment planning",category:"Psychopharmacology and Psychological Treatments",prompt:"Outline principles of safe treatment selection and monitoring in psychiatry.",max:20,modelAnswer:"Confirm diagnosis and treatment goals with the patient. Consider severity, comorbidity, physical health, pregnancy potential where relevant, previous response, interactions, risks and preferences. Discuss options and consent. Establish baseline monitoring appropriate to the medication, titrate and review response/adverse effects, support adherence, provide psychological/social interventions and plan ongoing review and relapse prevention.",rubric:[{label:"Indication and shared decision",points:5,feedback:"Clarify diagnosis, goals, alternatives, consent and preferences.",groups:[["diagnosis","goals"],["alternatives","consent"],["preference","shared"]]}, {label:"Safety and interactions",points:5,feedback:"Consider comorbidity, physical health, interactions and individual risks.",groups:[["comorbidity","physical"],["interaction","risk"],["pregnancy","preference"]]}, {label:"Monitoring",points:5,feedback:"Use relevant baseline/follow-up tests and assess adverse effects and response.",groups:[["baseline","monitoring"],["adverse effects","response"],["titrate","review"]]}, {label:"Holistic care",points:5,feedback:"Include psychological/social support, adherence and relapse prevention.",groups:[["psychological","social"],["adherence","support"],["relapse prevention","follow up"]]}]}]
