    essays:[{title:"Psychiatric emergency",category:"Psychiatric Emergencies and Clinical Risk",prompt:"Outline the immediate assessment and management of a severely agitated patient in an emergency setting.",max:20,modelAnswer:"Ensure staff/patient safety and call for appropriate assistance. Assess ABCs, vital signs, consciousness, injury, intoxication/withdrawal and medical causes. Use calm communication, de-escalation, space and reduced stimulation. Assess mental state, risk, capacity and likely causes. If medication or restraint is necessary for immediate safety, follow local protocol with monitoring and documentation. Reassess, treat underlying causes and plan ongoing care.",rubric:[{label:"Safety and team response",points:5,feedback:"Ensure safe environment, assistance and least restrictive approach.",groups:[["safety","assistance"],["environment","de escalation"],["least restrictive","team"]]}, {label:"Immediate medical assessment",points:5,feedback:"Assess ABCs, observations, consciousness, injury and medical/toxic causes.",groups:[["ABCs","vital signs"],["consciousness","injury"],["medical","intoxication"]]}, {label:"Risk and intervention",points:5,feedback:"Assess risk and use protocol-based medication/restraint only if needed, with monitoring.",groups:[["risk","mental state"],["protocol","medication"],["monitoring","documentation"]]}, {label:"Reassessment and plan",points:5,feedback:"Treat causes, reassess response and arrange ongoing care.",groups:[["treat","cause"],["reassess","response"],["ongoing","plan"]]}]}]
